<?php
defined('ABSPATH') || exit;
final class TNet_Community_Thread_View {
    public function find(string $post_id, bool $admin=false): ?array { $repo=new TNet_Community_Publisher_Repository(); $root=$repo->find_post($post_id); if (!$root) return null; $rows=$repo->list_thread($root['thread_id']); $visible=[]; foreach($rows as $row) { $state=$row['publication_state']; $allowed=in_array($state,['published','restored'],true); if (!$allowed && !$admin) { if (in_array($state,['deleted','retracted'],true)) $row['_tombstone']=true; else continue; } $row['_depth']=$this->depth($row,$rows); $row['_author_display']='Local synthetic author'; $visible[]=$this->safe($row); } return ['root'=>$this->safe($root),'rows'=>$visible,'thread_id'=>$root['thread_id']]; }
    private function depth(array $row,array $rows): int { $depth=0; $parent=$row['parent_post_id']; $seen=[]; while($parent && !isset($seen[$parent])) { $seen[$parent]=true; $depth++; foreach($rows as $candidate) if($candidate['post_id']===$parent) {$parent=$candidate['parent_post_id']; break;} } return min($depth,8); }
    private function safe(array $row): array { return ['post_id'=>$row['post_id'],'thread_id'=>$row['thread_id'],'parent_post_id'=>$row['parent_post_id'],'post_type'=>$row['post_type'],'title'=>$row['title'],'body'=>$row['body'],'publication_state'=>$row['publication_state'],'created_at'=>$row['created_at'],'published_at'=>$row['published_at'],'_depth'=>$row['_depth']??0,'_author_display'=>$row['_author_display']??'Local synthetic author','_tombstone'=>$row['_tombstone']??false]; }
}
